from pathlib import Path
from bs4 import BeautifulSoup
import shutil
R=Path('/workspace/work/deliverables/dockside');C=R/'collection/dockside';V=R/'review'
def save(n,h,intro='',title=None,late=False,lead=''):
 p=V/f'reassembled/slide_{n:02}.html';b=BeautifulSoup(p.read_text(),'html.parser');b.select_one('.slide')['class']=['slide','overrides'];b.select_one('.head')['class']=['head']+(['overrides'] if late else [])
 if title:b.select_one('.title').clear();b.select_one('.title').append(BeautifulSoup(title,'html.parser'))
 if b.select_one('.head>.lead'):b.select_one('.head>.lead').decompose()
 if lead:b.select_one('.head').append(BeautifulSoup('<p class="lead">'+lead+'</p>','html.parser'))
 q=b.select_one('.body');q.clear();q.append(BeautifulSoup(h,'html.parser'))
 if intro:q.append(BeautifulSoup('<div class="prose quiet" data-el="dockside-prose" style="grid-column:1 / span 12;grid-row:1 / span 6"><p>'+intro+'</p></div>','html.parser'))
 p.write_text(str(b))
def full(h,cls='group'):return '<div class="'+cls+'" style="grid-column:1 / span 12;grid-row:1 / span 6">'+h+'</div>'
def add(f,s):
 p=C/f'elements/{f}/element.css';p.write_text(p.read_text()+'\n'+s+'\n')
def aside(label,text):return '<div class="prose quiet" data-el="dockside-prose" style="grid-column:1 / span 3;grid-row:5 / span 2"><p><b>'+label+'</b>'+text+'</p></div>'
