#26 source issue/solution pairing, native contract nested lists.
def issueSide(title,tag,n,items,on=''):
 return f'<div class="side {on}"><b class="name"><span class="tag" data-el="dockside-tag">{tag}</span>{title}<div class="seat icon" data-ph="{n}"></div></b><div class="list check" data-el="dockside-list">'+''.join('<div class="item"><b class="name">'+t+'</b></div>' for t in items)+'</div></div>'
